const catalogUrl = (businessId) => {
  const origin = typeof window !== "undefined" ? window.location.origin : "https://eldalel-elshamel.online";
  return `${origin}/?catalog=business&businessId=${encodeURIComponent(businessId)}`;
};
const productUrl = (productId) => {
  const origin = typeof window !== "undefined" ? window.location.origin : "https://eldalel-elshamel.online";
  return `${origin}/?catalog=product&productId=${encodeURIComponent(productId)}`;
};
const productQrUrl = id => `https://api.qrserver.com/v1/create-qr-code/?size=360x360&margin=16&data=${encodeURIComponent(productUrl(id))}`;
const qrUrl = id => `https://api.qrserver.com/v1/create-qr-code/?size=360x360&margin=16&data=${encodeURIComponent(catalogUrl(id))}`;

async function downloadCatalogQr(id, name) {
  const url = qrUrl(id);
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error('QR download failed');
    const blob = await response.blob();
    const objectUrl = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = objectUrl;
    a.download = `QR-${String(name || id).replace(/[^\p{L}\p{N}._-]+/gu, '_')}.png`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(objectUrl);
  } catch {
    window.open(url, '_blank', 'noopener,noreferrer');
  }
}

function printCatalogQr(id, name) {
  const popup = window.open('', '_blank', 'width=620,height=760');
  if (!popup) return;
  const safeName = String(name || 'الدليل الشامل').replace(/[&<>"']/g, (ch) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const url = qrUrl(id);
  const pageUrl = catalogUrl(id);
  popup.document.open();
  popup.document.write(`<!doctype html><html dir="rtl"><head><meta charset="utf-8"><title>QR - ${safeName}</title><style>body{font-family:Arial,sans-serif;text-align:center;padding:35px;color:#0A1F44}img{width:360px;height:360px;max-width:90vw}.name{font-size:24px;font-weight:800;margin:15px}.url{font-size:12px;direction:ltr;word-break:break-all;margin:15px auto;max-width:520px}.brand{color:#9E7B28;font-weight:700;margin-top:18px}@media print{button{display:none}}</style></head><body><div class="brand">الدليل الشامل</div><div class="name">${safeName}</div><img src="${url}" alt="QR"><div class="url">${pageUrl}</div><button onclick="window.print()">طباعة</button><script>window.onload=function(){setTimeout(function(){window.print()},350)}</script></body></html>`);
  popup.document.close();
}

function cardColors(darkMode){
  return {
    bg: darkMode ? NAVY_DEEP : OFF_WHITE,
    card: darkMode ? "#0F2748" : "#fff",
    tc: darkMode ? "#fff" : NAVY,
    sub: darkMode ? "rgba(255,255,255,.58)" : GRAY,
    border: darkMode ? "rgba(201,168,76,.16)" : BORDER,
    input: darkMode ? "rgba(255,255,255,.07)" : "#fff"
  };
}
